"""Templates for the container image and the CI pipelines generated by ``pachifast new pipeline``.

The image installs the project with ``uv sync --frozen`` (reproducible, needs ``uv.lock``) in a builder stage,
then copies the virtual environment into a slim runtime stage that runs as a non-root user. No secret is baked
in: the configuration (``PACHIFAST_SECRET_KEY``, database URLs, ...) is passed as environment variables at runtime.
"""

import re
from dataclasses import dataclass, field
from enum import Enum
from pathlib import PurePosixPath

DEFAULT_PYTHON_VERSION = "3.12"
_PYTHON_VERSION_RE = re.compile(r"^\d+\.\d+$")
_INDEX_NAME_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_-]*$")
# Names of the build secrets (and of the CI secrets/variables) carrying the private index credentials.
INDEX_USERNAME_SECRET = "uv_index_username"
INDEX_PASSWORD_SECRET = "uv_index_password"
# Health check without curl: exits non-zero when /api/health/ is unreachable or not 2xx.
_HEALTHCHECK_CODE = (
    "import os, urllib.request; "
    "urllib.request.urlopen('http://127.0.0.1:%s/api/health/' % os.environ.get('PACHIFAST_PORT', '8000'), timeout=3)"
)


class Provider(str, Enum):
    """CI providers a pipeline can be generated for."""

    GITHUB = "github"
    GITLAB = "gitlab"
    GITEA = "gitea"
    ALL = "all"


@dataclass
class PipelineReport:
    """Outcome of ``create_pipeline``: what was written, what was left alone, and what to fix."""

    written: list[str] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)


def check_python_version(value: str) -> None:
    """Raise ``ValueError`` unless ``value`` looks like ``3.12`` (major.minor, used as the base image tag)."""
    if not _PYTHON_VERSION_RE.match(value.strip()):
        raise ValueError(f"Invalid Python version: {value!r} (expected major.minor, e.g. 3.12).")


def check_index_name(value: str) -> None:
    """Raise ``ValueError`` unless ``value`` is a valid uv index name (letters, digits, ``-`` and ``_``)."""
    if not _INDEX_NAME_RE.match(value):
        raise ValueError(f"Invalid index name: {value!r} (letters, digits, '-' and '_', starting with a letter).")


def index_env_prefix(index_name: str) -> str:
    """Return uv's environment variable prefix for the credentials of an index: ``UV_INDEX_<NAME>``."""
    return "UV_INDEX_" + re.sub(r"[^A-Za-z0-9]", "_", index_name).upper()


def _secret_mounts(index_name: str | None) -> str:
    """Return the ``RUN --mount`` options exposing the private index credentials to uv (empty without an index).

    The values exist only during the command: they never end up in an image layer.
    """
    if not index_name:
        return ""
    prefix = index_env_prefix(index_name)
    return (
        f"--mount=type=secret,id={INDEX_USERNAME_SECRET},env={prefix}_USERNAME \\\n"
        f"    --mount=type=secret,id={INDEX_PASSWORD_SECRET},env={prefix}_PASSWORD \\\n"
        "    "
    )


def _build_secrets_block(index_name: str | None, indent: str, fallback: tuple[str, str] | None = None) -> str:
    """Return the ``secrets:`` input of ``docker/build-push-action`` (empty without a private index).

    ``fallback`` names the secrets (username, password) used when ``UV_INDEX_USERNAME`` / ``UV_INDEX_PASSWORD`` are
    not defined.
    """
    if not index_name:
        return ""
    username = "secrets.UV_INDEX_USERNAME" + (f" || secrets.{fallback[0]}" if fallback else "")
    password = "secrets.UV_INDEX_PASSWORD" + (f" || secrets.{fallback[1]}" if fallback else "")
    return (
        f"{indent}secrets: |\n"
        f"{indent}  {INDEX_USERNAME_SECRET}=${{{{ {username} }}}}\n"
        f"{indent}  {INDEX_PASSWORD_SECRET}=${{{{ {password} }}}}\n"
    )


def check_ca_cert(value: str) -> None:
    """Raise ``ValueError`` unless ``value`` is a relative path (inside the project) of a ``.crt`` or ``.pem`` file."""
    path = PurePosixPath(value)
    if (
        path.is_absolute()
        or ".." in path.parts
        or path.suffix.lower() not in (".crt", ".pem")
        or not re.fullmatch(r"[A-Za-z0-9_./-]+", value)
    ):
        raise ValueError(
            f"Invalid --ca-cert {value!r}: expected a path inside the project such as certs/internal-ca.crt "
            "(a .crt or .pem file; letters, digits, '_', '-', '.', '/')."
        )


def _ca_block(ca_cert: str | None) -> str:
    """Dockerfile lines that make uv trust an internal certificate authority while it installs the dependencies."""
    if not ca_cert:
        return ""
    return (
        "# Internal certificate authority (the private index is served with it): trusted by uv while it installs.\n"
        f"COPY {ca_cert} /usr/local/share/ca-certificates/internal-ca.crt\n"
        "RUN update-ca-certificates\n"
        "ENV UV_SYSTEM_CERTS=1\n"
    )


def dockerfile_template(
    python_version: str = DEFAULT_PYTHON_VERSION, index_name: str | None = None, ca_cert: str | None = None
) -> str:
    """Return the multi-stage ``Dockerfile`` of a project.

    With ``index_name`` the two ``uv sync`` steps get the credentials of that private index through build secrets.
    With ``ca_cert`` (a path inside the project) the builder stage trusts that certificate authority.
    """
    mounts = _secret_mounts(index_name)
    ca_block = _ca_block(ca_cert)
    secret_note = (
        f"# Private index '{index_name}': build with --secret id={INDEX_USERNAME_SECRET},env=... "
        f"--secret id={INDEX_PASSWORD_SECRET},env=... (the CI pipelines do it).\n"
        if index_name
        else ""
    )
    return f"""# syntax=docker/dockerfile:1
# Build: docker build -t my-service .
# Run:   docker run --rm -p 8000:8000 -e PACHIFAST_SECRET_KEY=... -e PACHIFAST_AUTH_DATABASE_URL=... my-service
# The image contains no secrets: pass the configuration as environment variables at runtime.
{secret_note}
ARG PYTHON_VERSION={python_version}

# ---- builder: resolves the locked dependencies into /app/.venv (uv is not part of the final image) ----
FROM python:${{PYTHON_VERSION}}-slim AS builder
COPY --from=ghcr.io/astral-sh/uv:latest /uv /uvx /bin/
ENV UV_COMPILE_BYTECODE=1 \\
    UV_LINK_MODE=copy \\
    UV_PYTHON_DOWNLOADS=never
WORKDIR /app
{ca_block}# Needs uv.lock in the project (run `uv lock` and commit it): the build fails without it.
COPY pyproject.toml uv.lock ./
RUN {mounts}uv sync --frozen --no-dev --no-install-project
COPY . .
RUN {mounts}uv sync --frozen --no-dev
# Fails the build when the message catalogs disagree (the same codes and fields in every language); skipped when
# the installed pachifast has no `locale` command (older versions).
RUN if .venv/bin/pachifast locale --help >/dev/null 2>&1; then .venv/bin/pachifast locale check; fi

# ---- runtime ----
FROM python:${{PYTHON_VERSION}}-slim AS runtime
ENV PYTHONUNBUFFERED=1 \\
    PYTHONDONTWRITEBYTECODE=1 \\
    PATH="/app/.venv/bin:$PATH" \\
    PACHIFAST_HOST=0.0.0.0 \\
    PACHIFAST_PORT=8000 \\
    PACHIFAST_DEBUG=false
RUN groupadd --system --gid 10001 app \\
    && useradd --system --uid 10001 --gid app --home-dir /app --shell /usr/sbin/nologin app
WORKDIR /app
COPY --from=builder --chown=app:app /app /app
USER app
EXPOSE 8000
# Port from PACHIFAST_PORT: set the port through that variable, not only in a YAML file.
HEALTHCHECK --interval=30s --timeout=5s --start-period=20s --retries=3 \\
    CMD ["python", "-c", "{_HEALTHCHECK_CODE}"]
CMD ["pachifast", "serve"]
"""


def dockerignore_template() -> str:
    """Return the ``.dockerignore``: keeps secrets, VCS data and local artifacts out of the image."""
    return """# Secrets and local configuration: never in the image
.env
*.env
.env.*
!.env.example

# Version control, CI and container files
.git
.gitignore
.github
.gitlab-ci.yml
Dockerfile
.dockerignore

# Local artifacts
.venv
__pycache__
*.pyc
*.sqlite3
.pytest_cache
.ruff_cache
tests
"""


def github_workflow_template(index_name: str | None = None) -> str:
    """Return the GitHub Actions workflow that builds the image and pushes it to ghcr.io.

    With ``index_name`` the build gets the private index credentials from the repository secrets
    ``UV_INDEX_USERNAME`` and ``UV_INDEX_PASSWORD``.
    """
    return f"""name: Docker image

on:
  push:
    branches: [main]
    tags: ["v*"]

permissions:
  contents: read
  packages: write

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      # Registry image names must be lowercase.
      - name: Compute image name
        run: echo "IMAGE_NAME=ghcr.io/${{GITHUB_REPOSITORY,,}}" >> "$GITHUB_ENV"

      - uses: docker/setup-buildx-action@v3

      - uses: docker/login-action@v3
        with:
          registry: ghcr.io
          username: ${{{{ github.actor }}}}
          password: ${{{{ secrets.GITHUB_TOKEN }}}}

      - id: meta
        uses: docker/metadata-action@v5
        with:
          images: ${{{{ env.IMAGE_NAME }}}}
          tags: |
            type=ref,event=branch
            type=semver,pattern={{{{version}}}}
            type=semver,pattern={{{{major}}}}.{{{{minor}}}}
            type=sha
            type=raw,value=latest,enable={{{{is_default_branch}}}}

      - uses: docker/build-push-action@v6
        with:
          context: .
          push: true
          tags: ${{{{ steps.meta.outputs.tags }}}}
          labels: ${{{{ steps.meta.outputs.labels }}}}
          cache-from: type=gha
          cache-to: type=gha,mode=max
{_build_secrets_block(index_name, "          ")}"""


def gitlab_ci_template(index_name: str | None = None) -> str:
    """Return the GitLab CI pipeline that builds the image and pushes it to the project's container registry.

    With ``index_name`` the build reads the private index credentials from the CI/CD variables
    ``UV_INDEX_USERNAME`` and ``UV_INDEX_PASSWORD`` (masked and protected, set in the project settings).
    """
    secrets = (
        f"--secret id={INDEX_USERNAME_SECRET},env=UV_INDEX_USERNAME "
        f"--secret id={INDEX_PASSWORD_SECRET},env=UV_INDEX_PASSWORD "
        if index_name
        else ""
    )
    return f"""stages:
  - build

build-image:
  stage: build
  image: docker:latest
  services:
    - docker:dind
  variables:
    DOCKER_TLS_CERTDIR: "/certs"
  before_script:
    - echo "$CI_REGISTRY_PASSWORD" | docker login -u "$CI_REGISTRY_USER" --password-stdin "$CI_REGISTRY"
  script:
    - |
      if [ -n "$CI_COMMIT_TAG" ]; then
        TAGS="-t $CI_REGISTRY_IMAGE:$CI_COMMIT_TAG"
      else
        TAGS="-t $CI_REGISTRY_IMAGE:latest -t $CI_REGISTRY_IMAGE:$CI_COMMIT_SHORT_SHA"
      fi
      docker build --pull {secrets}$TAGS .
    - docker push --all-tags "$CI_REGISTRY_IMAGE"
  rules:
    - if: "$CI_COMMIT_TAG"
    - if: "$CI_COMMIT_BRANCH == $CI_DEFAULT_BRANCH"
"""


def gitea_workflow_template(index_name: str | None = None) -> str:
    """Return the Gitea Actions workflow that builds the image and pushes it to the Gitea container registry.

    The registry is the Gitea instance itself (taken from the server URL, nothing is hardcoded). The login uses the
    repository secret ``REGISTRY_TOKEN``: an access token of a user allowed to write packages (scope ``write:package``).
    There is no ``gha`` build cache: it is a GitHub service. With ``index_name`` the build gets the private index
    credentials from the secrets ``UV_INDEX_USERNAME`` and ``UV_INDEX_PASSWORD``, or from ``REGISTRY_USERNAME`` and
    ``REGISTRY_TOKEN`` when those are not defined (the same Gitea hosts the index). The optional variable
    ``BUILD_ADD_HOSTS`` (``host:ip``, comma separated) is passed to the build for registry names that the build
    container cannot resolve, and ``BUILDX_DRIVER=docker`` makes the build and the push use the runner's Docker
    daemon (which trusts the CA of an internal registry; the default ``docker-container`` builder does not).
    """
    return f"""name: Docker image

on:
  push:
    branches: [main]
    tags: ["v*"]

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      # Registry host = this Gitea instance; image names must be lowercase.
      - name: Compute registry and image name
        run: |
          REGISTRY="${{GITHUB_SERVER_URL#*://}}"
          echo "REGISTRY=${{REGISTRY}}" >> "$GITHUB_ENV"
          echo "IMAGE_NAME=${{REGISTRY}}/${{GITHUB_REPOSITORY,,}}" >> "$GITHUB_ENV"

      - uses: docker/setup-buildx-action@v3
        with:
          driver: ${{{{ vars.BUILDX_DRIVER || 'docker-container' }}}}

      - uses: docker/login-action@v3
        with:
          registry: ${{{{ env.REGISTRY }}}}
          username: ${{{{ github.actor }}}}
          password: ${{{{ secrets.REGISTRY_TOKEN }}}}

      - id: meta
        uses: docker/metadata-action@v5
        with:
          images: ${{{{ env.IMAGE_NAME }}}}
          tags: |
            type=ref,event=branch
            type=semver,pattern={{{{version}}}}
            type=semver,pattern={{{{major}}}}.{{{{minor}}}}
            type=sha
            type=raw,value=latest,enable={{{{is_default_branch}}}}

      - uses: docker/build-push-action@v6
        with:
          context: .
          push: true
          tags: ${{{{ steps.meta.outputs.tags }}}}
          labels: ${{{{ steps.meta.outputs.labels }}}}
          add-hosts: ${{{{ vars.BUILD_ADD_HOSTS }}}}
{_build_secrets_block(index_name, "          ", ("REGISTRY_USERNAME", "REGISTRY_TOKEN"))}"""
